    private class GlyphPath(
        val data: String,
        val fill: Boolean = false,
        val fillAlpha: Float = 1f,
        val evenOdd: Boolean = false,
        val strokeWidth: Float = 0f,
        val cap: StrokeCap = StrokeCap.Butt,
        val join: StrokeJoin = StrokeJoin.Miter,
    )

    private fun glyph(name: String, vararg paths: GlyphPath): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        )
        paths.forEach { path ->
            builder.addPath(
                pathData = addPathNodes(path.data),
                pathFillType = if (path.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = if (path.fill) SolidColor(Color.Black) else null,
                fillAlpha = path.fillAlpha,
                stroke = if (path.strokeWidth > 0f) SolidColor(Color.Black) else null,
                strokeLineWidth = path.strokeWidth,
                strokeLineCap = path.cap,
                strokeLineJoin = path.join,
            )
        }
        return builder.build()
    }
